    "title": "美政府暂停微软等多家科企外籍员工绿卡申请",
    "link": "https://m.thepaper.cn/detail/34216600",
    "pub_date": "2026-10-09 10:17:31",
    "author": "澎湃新闻记者 胡逸璠",
    "description": "当地时间10月8日，特朗普政府宣布将无限期暂停微软等多家科技公司参与一项允许企业为持有H-1B签证的外国技术劳工申请绿卡的计划。美国副总统万斯在华盛顿举行的新闻发布会上点名微软，称微软过去一年持续裁员，却仍大量申请H-1B签证及后续绿卡。",
