    "description": "据知情人士透露，OpenAI预计到今年年底年化营收将达到或超过700亿美元，增长主要来自企业业务扩张。知情人士表示，这家ChatGPT开发商截至9月底的年化营收约为500亿美元。年化营收是根据较短时期收入表现推算出的全年销售额。知情人士表示，OpenAI在最新一轮融资讨论过程中向投资者披露了上述数据。由于相关信息未公开，这些知情人士不愿具名。（新浪财经）",
