    "description": "中新网10月9日电 据最高人民检察院官方微博消息，新疆维吾尔自治区党委原常委、自治区政府原副主席陈伟俊涉嫌受贿一案，由国家监察委员会调查终结，移送检察机关审查起诉。最高人民检察院依法以涉嫌受贿罪对陈伟俊作出逮捕决定，并指定由安徽省滁州市人民检察院审查起诉。近日，滁州市人民检察院已向滁州市中级人民法院提起公诉。",
