    "description": "8月30日，住在浦东的摄影博主小刘从上海一路自驾前往一江之隔的启东市，她的目的地是千年古镇——传说中吕洞宾曾四次云游之地——吕四港镇。下午3点，她到达仙渔小镇，从红檐老街走到临海观景台。4点多来到吕四渔港，拍下岸边停泊的渔船。日落前赶到防波堤，晚上以一顿海鲜结束行程。沿途景点免门票，停车也免费。 小刘在社交媒体发布的吕四港照片。受访者 供图 她走过的这段海岸线，正是抖音、小红书等社交平台上备受推崇的长三角网红自驾线路——由中国国家地理杂…",
    "content": "8月30日，住在浦东的摄影博主小刘从上海一路自驾前往一江之隔的启东市，她的目的地是千年古镇——传说中吕洞宾曾四次云游之地——吕四港镇。下午3点，她到达仙渔小镇，从红檐老街走到临海观景台。4点多来到吕四渔港，拍下岸边停泊的渔船。日落前赶到防波堤，晚上以一顿海鲜结束行程。沿途景点免门票，停车也免费。 小刘在社交媒体发布的吕四港照片。受访者 供图 她走过的这段海岸线，正是抖音、小红书等社交平台上备受推崇的长三角网红自驾线路——由中国国家地理杂志与启东市携手打造的“最鲜公路”。这条串联起滨江绿廊、黄金海滩、通海垦牧、吕四渔…"
