    "content": "从《护工不是人》里的独居老人 Sue，到创业者口中父亲住院的照护经历，人形养老机器人承载着普遍期待。文章把照护拆成身体、情感与认知三类劳动，追问一台机器人要渡过哪三条河，才能真正走进老人的晚年。 这篇文章的起因，是前不久我采访了一家机器人公司，对方提到，创业的起点是父亲住院时的一次照护经历。 他发现，即使是最亲近的人，也很难在照护一个病人时做到面面俱到，于是开始琢磨，有没有一种机器，可以让我们老去的时候，更有尊严？ 这个念头很朴素，也跟大众对机器人的期待不谋而合。 过去两年，人形机器人在展会和舞台上又唱又跳，但如果…"
