    "content": "IT之家 10 月 9 日消息，当地时间 8 日，据《商业内幕》报道，安德鲁 · 加菲尔德在即将上映的电影《Artificial》中饰演 OpenAI CEO 萨姆 · 奥尔特曼，可这段表演经历并没有让他更加看好 AI。 相反，出演这部电影 让他对 AI 产生了疑虑 。“我有点害怕，也不太信任这项技术。那些开发 AI、鼓励大家使用 AI 的人，似乎连自己都不完全清楚它能做到什么。所以我个人觉得，这有点不负责任。” 加菲尔德曾使用 ChatGPT 查资料，也会把它当成“高级版谷歌”，但自己并不需要依靠 AI 开展演艺…"
